import type {FC} from 'react';
import React, {useCallback, useState} from 'react';

import {getConfig} from '@gravity-ui/uikit';
import type {MetaEntityV2} from '@weavix/tracker-api-types';

import {MetaEntityIcon} from '~/src/components/Icon/';
import {useLocalizedString} from '~/src/hooks/useLocalizedString';

import {cnMetaEntitiesSelect} from './MetaEntitiesSelect.classname';
import {EntitiesSuggest} from './components/EntitiesSuggest/EntitiesSuggest';
import type {EntitiesSuggestProps} from './components/EntitiesSuggest/EntitiesSuggest';
import {EntitiesSuggestItem} from './components/EntitiesSuggestItem/EntitiesSuggestItem';
import {defaultMessages} from './i18n';
import {getMetaEntityDisplay} from './utils/getMetaEntityDisplay';
import {getMetaEntityId} from './utils/getMetaEntityId';

type EntitiesSuggestPropsToOmit = 'getItemId' | 'getSuggestTextFromClickedItem' | 'renderItem';

export type MetaEntitiesSelectProps = Omit<
    EntitiesSuggestProps<MetaEntityV2>,
    EntitiesSuggestPropsToOmit
> & {
    className?: string;
    itemClassName?: string;
};

export const MetaEntitiesSelect: FC<MetaEntitiesSelectProps> = ({
    className,
    itemClassName,
    placeholder,
    text: initialText,
    onTextChange,
    ...suggestProps
}) => {
    const config = getConfig();
    const {t} = useLocalizedString(defaultMessages, config.lang);
    const [text, setText] = useState(initialText ?? '');
    const handleTextChange = useCallback(
        (value: string) => {
            setText(value);
            onTextChange?.(value);
        },
        [setText, onTextChange],
    );

    const renderItem = useCallback(
        (entity: MetaEntityV2) => {
            const entityName = getMetaEntityDisplay(entity);
            return (
                <EntitiesSuggestItem
                    key={entity.id}
                    id={entity.id}
                    name={entityName}
                    className={cnMetaEntitiesSelect('item', itemClassName)}
                    icon={<MetaEntityIcon entity={entity} />}
                />
            );
        },
        [itemClassName],
    );

    return (
        <EntitiesSuggest<MetaEntityV2>
            {...suggestProps}
            className={cnMetaEntitiesSelect(null, className)}
            renderItem={renderItem}
            placeholder={placeholder ?? t('placeholder')}
            getItemsOnMount
            showItemsOnNoText
            getItemId={getMetaEntityId}
            getSuggestTextFromClickedItem={getMetaEntityDisplay}
            text={text}
            onTextChange={handleTextChange}
        />
    );
};
